package com.example.rokidgeminisecretary;
import android.content.*;import org.json.*;import java.io.*;import java.util.*;
public final class AnswerCorrectionChecks {
 static int n;static void ok(boolean b){n++;if(!b)throw new AssertionError("answer corrections "+n);}interface Work{void run()throws Exception;}static void rejects(Work work)throws Exception{boolean rejected=false;try{work.run();}catch(IOException|IllegalArgumentException e){rejected=true;}ok(rejected);}
 public static int run(Context base)throws Exception{n=0;Context c=new ContextWrapper(base){public File getFilesDir(){File d=new File(base.getFilesDir(),"answer-corrections");d.mkdirs();return d;}};JSONObject source=new JSONObject().put("kind","Gemini").put("time",100).put("message","Original synthetic answer: value is 10").put("requestId","e".repeat(64));String id=UUID.randomUUID().toString();ok(AnswerCorrections.list(c).length()==0);ok(AnswerCorrections.view(c,source).getInt("revision")==0);JSONObject saved=AnswerCorrections.append(c,source,0,id,"The correct value is 20");ok(saved.getInt("revision")==1);ok(saved.getJSONObject("source").getString("message").equals(source.getString("message")));ok(saved.getJSONArray("corrections").getJSONObject(0).getString("text").equals("The correct value is 20"));ok(saved.getJSONArray("corrections").getJSONObject(0).getLong("at")>0);ok(!new String(ConversationWorkspace.file(c,"answer-corrections").readFully(),"UTF-8").contains("The correct value"));ok(AnswerCorrections.append(c,source,0,id,"The correct value is 20").getInt("revision")==1);rejects(()->AnswerCorrections.append(c,source,1,id,"Different content"));rejects(()->AnswerCorrections.append(c,source,0,UUID.randomUUID().toString(),"Stale correction"));ok(AnswerCorrections.view(c,source).getJSONArray("corrections").length()==1);rejects(()->AnswerCorrections.append(c,source,1,UUID.randomUUID().toString()," "));rejects(()->AnswerCorrections.append(c,source,1,"invalid","text"));rejects(()->AnswerCorrections.append(c,source,1,UUID.randomUUID().toString(),"x".repeat(2401)));rejects(()->AnswerCorrections.source(new JSONObject(source.toString()).put("kind","ユーザー")));JSONObject revised=new JSONObject(source.toString()).put("message","Original synthetic answer: value is 11");ok(!AnswerCorrections.key(source).equals(AnswerCorrections.key(revised)));ok(AnswerCorrections.view(c,revised).getJSONArray("corrections").length()==0);AnswerCorrections.append(c,source,1,UUID.randomUUID().toString(),"A later correction with <script>literal</script> text");ok(AnswerCorrections.list(c).length()==1);String text=AnswerCorrections.text(AnswerCorrections.view(c,source));ok(text.contains(source.getString("message"))&&text.contains("The correct value is 20")&&text.contains("later correction"));ok(text.contains("AIが確認した内容ではありません"));
 // Independent simultaneous append attempts: exactly one revision succeeds.
 java.util.concurrent.ExecutorService pool=java.util.concurrent.Executors.newFixedThreadPool(2);java.util.concurrent.CountDownLatch start=new java.util.concurrent.CountDownLatch(1);java.util.concurrent.atomic.AtomicInteger success=new java.util.concurrent.atomic.AtomicInteger();try{java.util.ArrayList<java.util.concurrent.Future<?>> futures=new java.util.ArrayList<>();for(int i=0;i<2;i++){final int index=i;futures.add(pool.submit(()->{try{start.await();AnswerCorrections.append(c,source,2,UUID.randomUUID().toString(),"concurrent "+index);success.incrementAndGet();}catch(IOException expected){}catch(Exception e){throw new RuntimeException(e);}}));}start.countDown();for(java.util.concurrent.Future<?> f:futures)f.get();}finally{pool.shutdownNow();}ok(success.get()==1);ok(AnswerCorrections.view(c,source).getInt("revision")==3);
 MainActivity owner=ReliabilityChecks.owner(c);ok(AnswerCorrections.resolve(owner,source).getString("message").equals(source.getString("message")));rejects(()->AnswerCorrections.resolve(owner,revised));for(int revision=3;revision<20;revision++)AnswerCorrections.append(c,source,revision,UUID.randomUUID().toString(),"correction "+revision);rejects(()->AnswerCorrections.append(c,source,20,UUID.randomUUID().toString(),"over limit"));ok(AnswerCorrections.view(c,source).getInt("revision")==20);return n;}
}
